<?php require_once 'config.php';require_login();$pageTitle='Meu perfil';$errors=[];$success='';$u=user();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';if($action==='dados'){$nome=trim($_POST['nome']??'');$email=strtolower(trim($_POST['email']??''));if($nome==='')$errors[]='Nome obrigatório.';if(!valid_email($email))$errors[]='E-mail inválido.';$s=db()->prepare('SELECT id FROM usuarios WHERE email=? AND id<>?');$s->execute([$email,$u['id']]);if($s->fetch())$errors[]='Este e-mail já está em uso.';if(!$errors){$s=db()->prepare('UPDATE usuarios SET nome=?,email=? WHERE id=?');$s->execute([$nome,$email,$u['id']]);refresh_user();$u=user();$success='Dados atualizados com sucesso.';}}elseif($action==='senha'){$atual=$_POST['atual']??'';$nova=$_POST['nova']??'';$conf=$_POST['confirmar']??'';$s=db()->prepare('SELECT senha FROM usuarios WHERE id=?');$s->execute([$u['id']]);$hash=$s->fetchColumn();if(!password_verify($atual,$hash))$errors[]='A senha atual está incorreta.';if(strlen($nova)<6)$errors[]='A nova senha deve ter pelo menos seis caracteres.';if($nova!==$conf)$errors[]='A confirmação não corresponde à nova senha.';if(!$errors){$s=db()->prepare('UPDATE usuarios SET senha=? WHERE id=?');$s->execute([password_hash($nova,PASSWORD_DEFAULT),$u['id']]);$success='Senha alterada com sucesso.';}}} $s=db()->prepare('SELECT * FROM usuarios WHERE id=?');$s->execute([$u['id']]);$data=$s->fetch();require 'includes/header.php'; ?>
<div class="page-top"><div><div class="eyebrow">Sua conta</div><h1 class="page-title">Meu perfil</h1></div></div><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(280px,1fr))"><form class="form-card" method="post"><h1>Informações pessoais</h1><p>Atualize seus dados de acesso.</p><?php foreach($errors as $er): ?><div class="alert danger"><?= e($er) ?></div><?php endforeach; ?><?php if($success): ?><div class="alert success"><?= e($success) ?></div><?php endif; ?><input type="hidden" name="csrf" value="<?= csrf() ?>"><input type="hidden" name="action" value="dados"><div class="field"><label>Nome</label><input name="nome" value="<?= e($data['nome']) ?>" required></div><div class="field"><label>E-mail</label><input type="email" name="email" value="<?= e($data['email']) ?>" required></div><div class="field"><label>Tipo de conta</label><input value="<?= e($data['tipo']) ?>" disabled></div><div class="field"><label>Cadastro</label><input value="<?= date('d/m/Y H:i',strtotime($data['criado_em'])) ?>" disabled></div><button class="btn">SALVAR DADOS</button></form><form class="form-card" method="post"><h1>Alterar senha</h1><p>Escolha uma senha segura com pelo menos seis caracteres.</p><input type="hidden" name="csrf" value="<?= csrf() ?>"><input type="hidden" name="action" value="senha"><div class="field"><label>Senha atual</label><input type="password" name="atual" required></div><div class="field"><label>Nova senha</label><input type="password" name="nova" minlength="6" required></div><div class="field"><label>Confirmar nova senha</label><input type="password" name="confirmar" minlength="6" required></div><button class="btn">ATUALIZAR SENHA</button></form></div><?php require 'includes/footer.php'; ?>
